import{_t as e,it as t,n,rt as r}from"./chunks/framework.BhEEDjPG.js";var i=JSON.parse(`{"title":"ADR 0006 — Metering is pass-through; users see a percentage","description":"","frontmatter":{},"headers":[],"relativePath":"reference/adr/0006-metering-pass-through.md","filePath":"reference/adr/0006-metering-pass-through.md"}`),a={name:`reference/adr/0006-metering-pass-through.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0006-—-metering-is-pass-through-users-see-a-percentage" tabindex="-1">ADR 0006 — Metering is pass-through; users see a percentage <a class="header-anchor" href="#adr-0006-—-metering-is-pass-through-users-see-a-percentage" aria-label="Permalink to “ADR 0006 — Metering is pass-through; users see a percentage”">​</a></h1><ul><li><strong>Status:</strong> Accepted</li><li><strong>Date:</strong> 2026-09-18 → 2026-09-19 (origin)</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>Usage needed to be limited per user and billed per organisation. Options for the counted unit: raw tokens (inflates a chat 14× with cached reads), billable tokens only (cost per counted token varied 8.9×), &quot;things created&quot; (a job&#39;s cost varied 2.4–4.6× with how it went).</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ul><li><strong>Bill what vendors bill you.</strong> Each turn produces vendor cost lines priced at the endpoint&#39;s rate; work served from own infrastructure costs nothing.</li><li><strong>Plan tokens</strong> (cost-weighted: input 1, cached 0.1, output 6, cache write 1 by default) are the unit caps count — measured r = 1.00 against cost — fixed to the primary model so a failover premium is never charged to the user.</li><li><strong>Users see a percentage</strong> of their cap and the reset time; never tokens, never &quot;N left&quot;.</li><li>The gateway keeps the counters and the ledger; a metering service (optional, fed by a buffered idempotent fail-open client) rates events and feeds a billing engine; the agent never talks to billing.</li><li>Per-model config, including price, lives on the endpoint.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><p>Ledger events carry opaque ids and enums only. Adding a vendor line (speech-to-text seconds, a paid lookup) is one <code>record()</code> call with a deterministic event id.</p><hr><p><small>Source: <a href="https://github.com/marg-adk/marg/blob/main/docs/adr/0006-metering-pass-through.md">docs/adr/0006-metering-pass-through.md</a> — edit it there; the site mirrors the repository.</small></p>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};